const SUPABASE_PAGE_SIZE=1000;

async function fetchAllSupabasePages<T>(fetchPage:(from:number,to:number)=>PromiseLike<{data:T[]|null;error:{message:string}|null}>){
  const rows:T[]=[];
  for(let from=0;;){
    const {data,error}=await fetchPage(from,from+SUPABASE_PAGE_SIZE-1);
    if(error)throw error;
    const page=data??[];
    if(!page.length)break;
    rows.push(...page);
    from+=page.length;
  }
  return rows;
}

async function fetchDirectory() {
  const client=getSupabaseBrowserClient();
  const [departmentResult,locationResult,employeeResult,holidayResult,leaveTypeResult,balanceResult,policyResult,profileResult]=await Promise.all([
    client.from("departments").select("id,name").order("name"),
    client.from("locations").select("id,name,latitude,longitude,geofence_radius_m").order("name"),
    fetchAllSupabasePages<DirectoryEmployeeRow>((from,to)=>client.from("employees").select("id,profile_id,employee_code,name,email,department_id,location_id,designation,reporting_manager_id,payroll_company,address,contact_number,emergency_contact_number,joined_on,exited_on,status").order("name").order("id").range(from,to)),
    client.from("holidays").select("id,name,holiday_date,holiday_type,location_id").order("holiday_date"),
    client.from("leave_types").select("id,name"),
    client.from("leave_balances").select("employee_id,leave_type_id,allocated,used,balance_year").eq("balance_year",new Date().getFullYear()),
    client.from("hr_policies").select("policy_type,settings").in("policy_type",["attendance","leave"]),
    client.from("profiles").select("id,role"),
  ]);
  if(departmentResult.error)throw departmentResult.error;
  if(locationResult.error)throw locationResult.error;
  if(holidayResult.error)throw holidayResult.error;
  if(leaveTypeResult.error)throw leaveTypeResult.error;
  if(balanceResult.error)throw balanceResult.error;
  if(policyResult.error)throw policyResult.error;
  if(profileResult.error)throw profileResult.error;
  const departmentRows=departmentResult.data as unknown as {id:string;name:string}[];
  const locationRows=locationResult.data as unknown as {id:string;name:string;latitude:number|null;longitude:number|null;geofence_radius_m:number}[];
  const employeeRows=employeeResult;
  const holidayRows=holidayResult.data as unknown as {id:string;name:string;holiday_date:string;holiday_type:string;location_id:string|null}[];
  const leaveTypeRows=leaveTypeResult.data as unknown as {id:string;name:string}[];
  const balanceRows=balanceResult.data as unknown as {employee_id:string;leave_type_id:string;allocated:number;used:number}[];
  const policyRows=policyResult.data as unknown as {policy_type:string;settings:Record<string,unknown>}[];
  const profileRows=profileResult.data as unknown as {id:string;role:string}[];
  const attendanceSettings=policyRows.find(policy=>policy.policy_type==="attendance")?.settings??{};
  const leaveSettings=policyRows.find(policy=>policy.policy_type==="leave")?.settings??{};
  const departmentById=new Map(departmentRows.map(item=>[item.id,item.name]));
  const locationById=new Map(locationRows.map(item=>[item.id,item.name]));
  const employeeById=new Map(employeeRows.map(item=>[item.id,item.name]));
  const employeeCodeById=new Map(employeeRows.map(item=>[item.id,item.employee_code]));
  const roleByProfileId=new Map(profileRows.map(item=>[item.id,item.role]));
  const leaveTypeById=new Map(leaveTypeRows.map(item=>[item.id,item.name]));
  const leaveBalances:Record<string,LeaveBalance>={};
  for(const row of balanceRows){const employeeCode=employeeCodeById.get(row.employee_id);if(!employeeCode)continue;const current=leaveBalances[employeeCode]??{casual:0,sick:0,earned:0,workFromHome:0};const available=Math.max(0,Number(row.allocated)-Number(row.used));const type=leaveTypeById.get(row.leave_type_id)?.toLowerCase();if(type==="casual leave")current.casual=available;else if(type==="sick leave")current.sick=available;else if(type==="earned leave")current.earned=available;else if(type==="work from home")current.workFromHome=available;leaveBalances[employeeCode]=current}
  return {
    departments:departmentRows.map(item=>item.name),
    locations:locationRows.map(item=>item.name),
    locationSettings:locationRows.map(item=>({name:item.name,latitude:item.latitude===null?"":String(item.latitude),longitude:item.longitude===null?"":String(item.longitude),radius:Number(item.geofence_radius_m??1000),configured:item.latitude!==null&&item.longitude!==null})),
    employees:employeeRows.map((item):Employee=>({
      databaseId:item.id,id:item.employee_code,name:item.name,email:item.email,department:departmentById.get(item.department_id??"")??"Unassigned",
      location:locationById.get(item.location_id??"")??"Unassigned",designation:item.designation,
      manager:employeeById.get(item.reporting_manager_id??"")??"Not assigned",payrollCompany:item.payroll_company??"Not assigned",address:item.address??"",
      contact:item.contact_number??"",emergency:item.emergency_contact_number??"",joinedOn:item.joined_on,
      exitedOn:item.exited_on??"",status:item.status==="inactive"?"Inactive":"Active",accessRole:roleByProfileId.get(item.profile_id??"")==="admin"?"Admin":roleByProfileId.get(item.profile_id??"")==="manager"?"Manager":"Employee",
    })),
    holidays:holidayRows.map((item):Holiday=>({id:item.id,name:item.name,date:item.holiday_date,type:"National",location:item.location_id?locationById.get(item.location_id)??"Unknown location":"All locations"})),
    leaveBalances,
    leaveTypes:leaveTypeRows.map(item=>({id:item.id,name:item.name})),
    attendancePolicy:{workday:String(attendanceSettings.workday_start??"09:30"),grace:String(attendanceSettings.grace_minutes??15),hours:String(attendanceSettings.required_hours??8),autoAbsent:Boolean(attendanceSettings.auto_absent??true),attendanceRegularizationDays:String(attendanceSettings.attendance_regularization_days??60),overtimeRegularizationDays:String(attendanceSettings.overtime_regularization_days??3)} as AttendancePolicy,
    leavePolicy:{casual:String(leaveSettings.casual_days??4),sick:String(leaveSettings.sick_days??4),earned:String(leaveSettings.earned_days??12),carryForward:Boolean(leaveSettings.carry_forward??true)} as LeavePolicy,
  };
}

function formatIndianTime(date = new Date()) { return new Intl.DateTimeFormat("en-IN",{timeZone:INDIA_TIME_ZONE,hour:"2-digit",minute:"2-digit",hour12:true}).format(date).toUpperCase(); }
function errorMessage(error: unknown, fallback: string) { if (error instanceof Error) return error.message; if (error && typeof error === "object" && "message" in error && typeof error.message === "string") return error.message; return fallback; }
async function functionError(error: unknown, fallback: string) { if (error && typeof error === "object" && "context" in error) { const response=(error as {context?:unknown}).context; if (response instanceof Response) { try { const payload=await response.clone().json() as {error?:string}; if (payload.error) return payload.error; } catch {} } } return errorMessage(error,fallback); }

async function invokeAuthenticatedFunction(name:string,body:Record<string,unknown>){
  const client=getSupabaseBrowserClient();
  const getUsableSession=async(forceRefresh=false)=>{
    if(forceRefresh){const {data,error}=await client.auth.refreshSession();if(error||!data.session)throw new Error("Your session has expired. Please sign in again.");return data.session}
    const {data,error}=await client.auth.getSession();if(error||!data.session)throw new Error("Your session has expired. Please sign in again.");
    if((data.session.expires_at??0)*1000<=Date.now()+60000){const refreshed=await client.auth.refreshSession();if(refreshed.error||!refreshed.data.session)throw new Error("Your session has expired. Please sign in again.");return refreshed.data.session}
    return data.session;
  };
  let session=await getUsableSession();
  let result=await client.functions.invoke(name,{body,headers:{Authorization:`Bearer ${session.access_token}`}});
  const status=result.error&&typeof result.error==="object"&&"context" in result.error&&(result.error as {context?:Response}).context instanceof Response?(result.error as {context:Response}).context.status:0;
  if(status===401){session=await getUsableSession(true);result=await client.functions.invoke(name,{body,headers:{Authorization:`Bearer ${session.access_token}`}})}
  return result;
}

function formatReportTime(value:string|null){if(!value)return "—";return new Intl.DateTimeFormat("en-IN",{timeZone:INDIA_TIME_ZONE,hour:"2-digit",minute:"2-digit",hour12:true}).format(new Date(value)).toUpperCase()}
function formatReportDate(value:string){return new Intl.DateTimeFormat("en-IN",{timeZone:"UTC",day:"2-digit",month:"short",year:"numeric"}).format(new Date(`${value}T00:00:00Z`))}
function titleCase(value:string){return value.replace(/_/g," ").replace(/\b\w/g,letter=>letter.toUpperCase())}
function indianDate(){return new Intl.DateTimeFormat("en-CA",{timeZone:INDIA_TIME_ZONE,year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date())}
function countDaysExceptSundays(from:string,to:string){const date=new Date(`${from}T00:00:00Z`);const end=new Date(`${to}T00:00:00Z`);let count=0;while(date<=end){if(date.getUTCDay()!==0)count++;date.setUTCDate(date.getUTCDate()+1)}return Math.max(0,count)}

function mobileLocationError(error:unknown){
  const code=error&&typeof error==="object"&&"code" in error?Number(error.code):0;
  if(code===1)return new Error("Location permission is blocked. On your phone, open this portal in Chrome or Safari, allow Location access, and enable Precise location.");
  if(code===3)return new Error("Your phone could not get a GPS location in time. Turn on Location/GPS, move near a window or outdoors, and try again.");
  return new Error("Your phone could not determine its current location. Turn on Location/GPS and try again in Chrome or Safari.");
}

async function getAttendanceLocation(){
  if(!window.isSecureContext)throw new Error("Location access requires the secure HTTPS portal.");
  if(!navigator.geolocation)throw new Error("Location services are not supported by this browser. Open the portal in Chrome or Safari.");
  const locate=(options:PositionOptions)=>new Promise<GeolocationPosition>((resolve,reject)=>navigator.geolocation.getCurrentPosition(resolve,reject,options));
  try{return await locate({enableHighAccuracy:true,timeout:20000,maximumAge:60000})}
  catch(firstError){
    const code=firstError&&typeof firstError==="object"&&"code" in firstError?Number(firstError.code):0;
    if(code===1)throw mobileLocationError(firstError);
    try{return await locate({enableHighAccuracy:false,timeout:15000,maximumAge:300000})}
    catch(fallbackError){throw mobileLocationError(fallbackError)}
  }
}

async function fetchCurrentUser(authId:string,email:string):Promise<CurrentUser>{
  const client=getSupabaseBrowserClient();
  const [profileResult,employeeResult]=await Promise.all([
    client.from("profiles").select("full_name,role").eq("id",authId).single(),
    client.from("employees").select("id,employee_code,name,reporting_manager_id").eq("profile_id",authId).maybeSingle(),
  ]);
  if(profileResult.error)throw profileResult.error;
  if(employeeResult.error)throw employeeResult.error;
  const profile=profileResult.data as {full_name:string;role:string};
  const employee=employeeResult.data as {id:string;employee_code:string;name:string;reporting_manager_id:string|null}|null;
  let managerName="Not assigned";let inferredRole:Role=profile.role==="admin"?"Admin":profile.role==="manager"?"Manager":"Employee";
  if(employee?.reporting_manager_id){const managerResult=await client.rpc("get_my_manager_name" as never) as unknown as {data:string|null;error:unknown};if(!managerResult.error&&managerResult.data)managerName=managerResult.data}
  if(employee&&inferredRole==="Employee"){const {count}=await client.from("employees").select("id",{count:"exact",head:true}).eq("reporting_manager_id",employee.id);if((count??0)>0)inferredRole="Manager"}
  return {authId,email,name:employee?.name||profile.full_name||email.split("@")[0],role:inferredRole,employeeDatabaseId:employee?.id,employeeCode:employee?.employee_code,managerName};
}

async function fetchAttendanceReport(employees:Employee[],from:string,to:string){
  const client=getSupabaseBrowserClient();
  const reportTo=to>indianDate()?indianDate():to;
  if(from>reportTo)return [];
  type AttendanceRecord={employee_id:string;attendance_date:string;check_in:string|null;check_out:string|null;working_hours:number|null;attendance_status:string;approval_status:string;is_regularization:boolean;regularization_reason:string|null;original_check_in:string|null;original_check_out:string|null;original_working_hours:number|null};
  type LeaveRecord={employee_id:string;leave_type_id:string;from_date:string;to_date:string;status:string;reason:string|null};
  type LeaveTypeRecord={id:string;name:string};
  type HolidayRecord={holiday_date:string};
  const [attendanceRecords,leaveRecords,leaveTypeRecords,holidayRecords]=await Promise.all([
    fetchAllSupabasePages<AttendanceRecord>((pageFrom,pageTo)=>client.from("attendance").select("employee_id,attendance_date,check_in,check_out,working_hours,attendance_status,approval_status,is_regularization,regularization_reason,original_check_in,original_check_out,original_working_hours").gte("attendance_date",from).lte("attendance_date",reportTo).order("id").range(pageFrom,pageTo)),
    fetchAllSupabasePages<LeaveRecord>((pageFrom,pageTo)=>client.from("leave_requests").select("employee_id,leave_type_id,from_date,to_date,status,reason").lte("from_date",reportTo).gte("to_date",from).order("id").range(pageFrom,pageTo)),
    fetchAllSupabasePages<LeaveTypeRecord>((pageFrom,pageTo)=>client.from("leave_types").select("id,name").order("id").range(pageFrom,pageTo)),
    fetchAllSupabasePages<HolidayRecord>((pageFrom,pageTo)=>client.from("holidays").select("holiday_date").eq("holiday_type","National").gte("holiday_date",from).lte("holiday_date",reportTo).order("id").range(pageFrom,pageTo)),
  ]);
  const attendanceByEmployeeDate=new Map(attendanceRecords.map(record=>[`${record.employee_id}:${record.attendance_date}`,record]));
  const leaveTypeById=new Map(leaveTypeRecords.map(item=>[item.id,item.name]));
  const nationalHolidayDates=new Set(holidayRecords.map(item=>item.holiday_date));
  const leavesByEmployee=new Map<string,LeaveRecord[]>();
  for(const leave of leaveRecords){const current=leavesByEmployee.get(leave.employee_id)??[];current.push(leave);leavesByEmployee.set(leave.employee_id,current)}
  const dates:string[]=[];const cursor=new Date(`${from}T00:00:00Z`);const last=new Date(`${reportTo}T00:00:00Z`);while(cursor<=last){if(cursor.getUTCDay()!==0)dates.push(cursor.toISOString().slice(0,10));cursor.setUTCDate(cursor.getUTCDate()+1)}
  const rows:AttendanceReportRow[]=[];
  for(const employee of employees){
    if(!employee.databaseId)continue;
    for(const date of dates){
      if(employee.joinedOn&&date<employee.joinedOn)continue;
      if(employee.exitedOn&&date>employee.exitedOn)continue;
      const attendanceRecord=attendanceByEmployeeDate.get(`${employee.databaseId}:${date}`);
      const requests=(leavesByEmployee.get(employee.databaseId)??[]).filter(leave=>leave.from_date<=date&&leave.to_date>=date);
      const isWorkFromHome=(leave:LeaveRecord)=>{const name=(leaveTypeById.get(leave.leave_type_id)??"").trim().toLowerCase();return name==="work from home"||name==="wfh"};
      const approvedWorkFromHome=requests.find(leave=>isWorkFromHome(leave)&&leave.status.toLowerCase()==="approved");
      const approvedLeave=requests.find(leave=>!isWorkFromHome(leave)&&leave.status.toLowerCase()==="approved");
      const pendingOrRejectedRequest=requests.find(isWorkFromHome)??requests.find(leave=>!isWorkFromHome(leave));
      const leaveRequest=approvedWorkFromHome??approvedLeave??pendingOrRejectedRequest;
      const isNationalHoliday=nationalHolidayDates.has(date);
      const hours=Number(attendanceRecord?.working_hours??0);
      const hasCompletedAttendance=Boolean(attendanceRecord?.check_in&&attendanceRecord?.check_out);
      const isRegularization=Boolean(attendanceRecord?.is_regularization);
      const eligibleAttendance=hasCompletedAttendance&&(!isRegularization||attendanceRecord?.approval_status.toLowerCase()==="approved");
      const hoursStatus=hours>8?"Present":hours>=4?"Half day":"Absent";
      const attendanceStatus=isNationalHoliday?"Holiday":approvedWorkFromHome?"Work from home":approvedLeave?"Leave":eligibleAttendance?hoursStatus:"Absent";
      const approval=isNationalHoliday?"Not applicable":approvedWorkFromHome||approvedLeave?"Approved":hasCompletedAttendance&&!isRegularization?"Not required":isRegularization?titleCase(attendanceRecord?.approval_status??"pending"):pendingOrRejectedRequest?titleCase(pendingOrRejectedRequest.status):"Not applicable";
      const whole=Math.floor(hours);
      const minutes=Math.round((hours-whole)*60);
      const originalHours=Number(attendanceRecord?.original_working_hours??0);
      const originalWhole=Math.floor(originalHours);
      const originalMinutes=Math.round((originalHours-originalWhole)*60);
      rows.push({employeeId:employee.id,employeeName:employee.name,department:employee.department,location:employee.location,date,checkIn:formatReportTime(attendanceRecord?.check_in??null),checkOut:formatReportTime(attendanceRecord?.check_out??null),originalCheckIn:isRegularization?formatReportTime(attendanceRecord?.original_check_in??null):"—",originalCheckOut:isRegularization?formatReportTime(attendanceRecord?.original_check_out??null):"—",originalWorkingHours:isRegularization&&attendanceRecord?.original_check_out?`${originalWhole}h ${originalMinutes}m`:"—",workingHours:attendanceRecord?.check_out?`${whole}h ${minutes}m`:"—",workingHoursNumber:hours,attendance:attendanceStatus,approval,regularizationApproval:isRegularization?titleCase(attendanceRecord?.approval_status??"pending"):"Not requested",regularizationReason:attendanceRecord?.regularization_reason?.trim()||"—",leaveType:leaveRequest?(leaveTypeById.get(leaveRequest.leave_type_id)??"Leave"):"—",leaveApproval:leaveRequest?titleCase(leaveRequest.status):"Not requested",leaveReason:leaveRequest?.reason?.trim()||"—"});
    }
  }
  return rows.sort((a,b)=>b.date.localeCompare(a.date)||a.employeeName.localeCompare(b.employeeName));
}

async function fetchAttendanceApprovals(employees:Employee[],ownEmployeeDatabaseId?:string){
  const {data,error}=await getSupabaseBrowserClient().from("attendance").select("id,employee_id,attendance_date,check_in,check_out,working_hours,is_regularization,regularization_reason").eq("approval_status","pending").eq("is_regularization",true).not("check_out","is",null).order("attendance_date",{ascending:false});
  if(error)throw error;
  const employeeByDatabaseId=new Map(employees.filter(employee=>employee.databaseId).map(employee=>[employee.databaseId as string,employee]));
  return (data as unknown as {id:string;employee_id:string;attendance_date:string;check_in:string|null;check_out:string|null;working_hours:number|null;is_regularization:boolean;regularization_reason:string|null}[]).flatMap((record):AttendanceApprovalRow[]=>{const employee=employeeByDatabaseId.get(record.employee_id);if(!employee||record.employee_id===ownEmployeeDatabaseId)return [];const hours=Number(record.working_hours??0);return [{id:record.id,employeeId:employee.id,employeeName:employee.name,date:record.attendance_date,checkIn:formatReportTime(record.check_in),checkOut:formatReportTime(record.check_out),workingHours:record.check_out?`${Math.floor(hours)}h ${Math.round((hours-Math.floor(hours))*60)}m`:"In progress",isRegularization:Boolean(record.is_regularization),reason:record.regularization_reason??""}]});
}

async function fetchLeaveRequests(employees:Employee[],leaveTypes:LeaveType[]){
  const {data,error}=await getSupabaseBrowserClient().from("leave_requests").select("id,employee_id,leave_type_id,from_date,to_date,days,reason,status").order("created_at",{ascending:false});
  if(error)throw error;
  const employeeByDatabaseId=new Map(employees.filter(employee=>employee.databaseId).map(employee=>[employee.databaseId as string,employee]));
  const leaveTypeById=new Map(leaveTypes.map(item=>[item.id,item.name]));
  return (data as unknown as {id:string;employee_id:string;leave_type_id:string;from_date:string;to_date:string;days:number;reason:string;status:string}[]).flatMap((record):LeaveRequestRow[]=>{const employee=employeeByDatabaseId.get(record.employee_id);if(!employee)return [];return [{id:record.id,employeeDatabaseId:record.employee_id,employeeId:employee.id,name:employee.name,type:leaveTypeById.get(record.leave_type_id)??"Leave",fromDate:record.from_date,toDate:record.to_date,days:Number(record.days),manager:employee.manager,status:titleCase(record.status),reason:record.reason}]});
}

async function fetchOvertimeRequests(employees:Employee[]){
  type OvertimeRecord={id:string;employee_id:string;overtime_date:string;from_time:string;to_time:string;hours:number;reason:string;status:string;is_regularization:boolean};
  const data=await fetchAllSupabasePages<OvertimeRecord>((from,to)=>getSupabaseBrowserClient().from("overtime_requests").select("id,employee_id,overtime_date,from_time,to_time,hours,reason,status,is_regularization").order("overtime_date",{ascending:false}).order("id").range(from,to));
  const employeeByDatabaseId=new Map(employees.filter(employee=>employee.databaseId).map(employee=>[employee.databaseId as string,employee]));
  return data.flatMap((record):OvertimeRequestRow[]=>{const employee=employeeByDatabaseId.get(record.employee_id);return employee?[{id:record.id,employeeDatabaseId:record.employee_id,employeeId:employee.id,name:employee.name,department:employee.department,date:record.overtime_date,fromTime:record.from_time.slice(0,5),toTime:record.to_time.slice(0,5),hours:Number(record.hours),manager:employee.manager,status:titleCase(record.status),reason:record.reason,isRegularization:Boolean(record.is_regularization)}]:[]});
}

function downloadAttendanceReport(reportRows: AttendanceReportRow[], month:string) {
  const rows = [["EMP ID","Name","Location","Original check in (IST)","Original check out (IST)","Original working hours","Final check in (IST)","Final check out (IST)","Final working hours","Date","Actual attendance","Manager approval","Regularisation approval","Regularisation reason","Leave / WFH request","Leave approval","Leave reason"],...reportRows.map(row=>[row.employeeId,row.employeeName,row.location,row.originalCheckIn,row.originalCheckOut,row.originalWorkingHours,row.checkIn,row.checkOut,row.workingHours,formatReportDate(row.date),row.attendance,row.approval,row.regularizationApproval,row.regularizationReason,row.leaveType,row.leaveApproval,row.leaveReason])];
  const escapeXml=(value:string)=>value.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
  const table=rows.map(row=>`<Row>${row.map(value=>`<Cell><Data ss:Type="String">${escapeXml(value)}</Data></Cell>`).join("")}</Row>`).join("");
  const workbook=`<?xml version="1.0"?><Workbook xmlns="urn:schemas-microsoft-com:office:spreadsheet" xmlns:ss="urn:schemas-microsoft-com:office:spreadsheet"><Worksheet ss:Name="Attendance Report"><Table>${table}</Table></Worksheet></Workbook>`;
  const url=URL.createObjectURL(new Blob([workbook],{type:"application/vnd.ms-excel;charset=utf-8"})); const link=document.createElement("a"); link.href=url; link.download=`Huma-Attendance-Report-${month}.xls`; document.body.appendChild(link); link.click(); link.remove(); window.setTimeout(()=>URL.revokeObjectURL(url),1000);
}

